    CCharString      ScriptName;                   // +0x74
    unsigned char    _pad78[0x93 - 0x78];
    unsigned char    NotPausedDuringCutscenes : 1; // +0x93 bit 0
    unsigned char    DeathPersistent : 1;          // +0x93 bit 1
